/*
 * prog53_dfs_cycle.c
 *
 * Detect whether a directed graph (with at most 8 vertices, numbered 0‑7)
 * contains a cycle.  The graph is supplied on the command line as a list
 * of directed edges, each edge given by two integer arguments “src dst”.
 *
 *   ./prog53_dfs_cycle 0 1 1 2 2 0
 *
 * If any argument is not a non‑negative integer in the range [0,7],
 * the program prints “INVALID_INPUT”.  Otherwise it prints
 *   CYCLE   – if a directed cycle exists,
 *   ACYCLIC – if the graph is acyclic.
 *
 * The original binary was heavily obfuscated; the logic above is the
 * behaviour that the de‑obfuscated code implements.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8                     /* maximum number of vertices */

static int  adj[MAXV][MAXV];        /* adjacency matrix */
static int  color[MAXV];           /* 0 = unvisited, 1 = visiting, 2 = visited */
static bool found_cycle = false;   /* set to true when a back‑edge is seen */

/* Depth‑first search that also detects a back‑edge (cycle). */
static void dfs(int u)
{
    int v;

    /* If a cycle has already been found we can stop early. */
    if (found_cycle)
        return;

    color[u] = 1;                  /* mark as “visiting” */

    for (v = 0; v < MAXV; ++v) {
        if (!adj[u][v])
            continue;             /* no edge u→v */

        if (color[v] == 0) {       /* tree edge */
            dfs(v);
            if (found_cycle)
                return;
        } else if (color[v] == 1) {/* back edge → cycle */
            found_cycle = true;
            return;
        }
        /* edges to already‑finished vertices (color == 2) are ignored */
    }

    color[u] = 2;                  /* mark as “finished” */
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    int i, src, dst;
    int edge_cnt = 0;              /* number of edge arguments processed */

    /* ------------------------------------------------------------------
     * Input validation
     * ------------------------------------------------------------------ */
    if ((argc - 1) % 2 != 0) {     /* must be an even number of arguments */
        puts("INVALID_INPUT");
        return 1;
    }

    /* Initialise adjacency matrix and colour array */
    for (i = 0; i < MAXV; ++i) {
        color[i] = 0;
        for (int j = 0; j < MAXV; ++j)
            adj[i][j] = 0;
    }

    /* Parse edge list */
    for (i = 1; i + 1 < argc; i += 2) {
        char *endptr;

        src = (int)strtol(argv[i], &endptr, 10);
        if (*endptr != '\0' || src < 0 || src >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        dst = (int)strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0' || dst < 0 || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[src][dst] = 1;          /* directed edge src → dst */
        ++edge_cnt;
    }

    /* ------------------------------------------------------------------
     * Cycle detection (DFS from every unvisited vertex)
     * ------------------------------------------------------------------ */
    for (i = 0; i < MAXV; ++i) {
        if (color[i] == 0)
            dfs(i);
        if (found_cycle)
            break;
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
